'use strict';
// Locally synthesized sounds: no network, audio files, or speech service required.
const SFX_BOOST=4;let masterGain=null,sfxVolume=.45;const activeSounds=new Set();
try{const p=JSON.parse(localStorage.getItem('sakura-audio')||'null');sound=p?.enabled??true;sfxVolume=p?.volume??.45}catch{sound=true}
function audioReady(){if(!sound)return false;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();if(!masterGain){masterGain=audioCtx.createGain();masterGain.gain.value=sfxVolume*SFX_BOOST;masterGain.connect(audioCtx.destination)}if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});return true}catch{return false}}
function tone(freq,at,duration,type='sine',gain=.14,end=freq){let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,at);o.frequency.exponentialRampToValueAtTime(end,at+duration);g.gain.setValueAtTime(.0001,at);g.gain.exponentialRampToValueAtTime(gain,at+.008);g.gain.exponentialRampToValueAtTime(.0001,at+duration);o.connect(g).connect(masterGain);activeSounds.add(o);o.onended=()=>{activeSounds.delete(o);o.disconnect();g.disconnect()};o.start(at);o.stop(at+duration+.02)}
function clickNoise(at){let b=audioCtx.createBuffer(1,Math.ceil(audioCtx.sampleRate*.045),audioCtx.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*Math.exp(-i/(d.length*.12));let n=audioCtx.createBufferSource(),g=audioCtx.createGain(),filter=audioCtx.createBiquadFilter();n.buffer=b;filter.type='highpass';filter.frequency.value=1700;g.gain.value=.16;n.connect(filter).connect(g).connect(masterGain);activeSounds.add(n);n.onended=()=>{activeSounds.delete(n);n.disconnect();filter.disconnect();g.disconnect()};n.start(at)}
function playSfx(event){if(!sound||!audioReady())return;const t=audioCtx.currentTime+.01;if(event==='discard'){clickNoise(t);tone(1350,t,.065,'triangle',.13,680);tone(430,t+.012,.085,'sine',.08,260);return}const patterns={select:[[720,0,.06]],start:[[392,0,.18],[494,.12,.2],[587,.24,.3]],riichi:[[440,0,.13],[659,.10,.17],[880,.23,.35]],pon:[[523,0,.16],[784,.13,.23]],chi:[[587,0,.14],[740,.1,.2]],kan:[[330,0,.19],[494,.12,.22],[659,.25,.34]],tsumo:[[523,0,.3],[659,.12,.3],[784,.24,.35],[1047,.4,.65]],ron:[[392,0,.16],[523,.12,.25],[784,.26,.45],[988,.4,.5]],draw:[[440,0,.25],[392,.19,.3],[330,.38,.42]],finish:[[523,0,.3],[659,.16,.3],[784,.32,.35],[1047,.5,.75]]};for(const [f,a,d] of patterns[event]||patterns.select)tone(f,t+a,d,event==='kan'?'triangle':'sine',event==='select'?.09:.17)}
beep=()=>playSfx('discard');
function updateAudioControls(){const b=$('#sound');b.textContent='音 '+(sound?'ON':'OFF');b.setAttribute('aria-pressed',String(sound));$('#volume').value=Math.round(sfxVolume*100);$('#volume').setAttribute('aria-valuetext',Math.round(sfxVolume*100)+'%');try{localStorage.setItem('sakura-audio',JSON.stringify({enabled:sound,volume:sfxVolume}))}catch{}}
$('#sound').onclick=()=>{sound=!sound;if(!sound){for(const n of activeSounds)try{n.stop()}catch{}if(masterGain)masterGain.gain.setValueAtTime(0,audioCtx.currentTime)}else{audioReady();if(masterGain)masterGain.gain.setValueAtTime(sfxVolume*SFX_BOOST,audioCtx.currentTime);playSfx('select')}updateAudioControls()};
$('#volume').oninput=e=>{sfxVolume=Number(e.target.value)/100;if(masterGain)masterGain.gain.setTargetAtTime(sound?sfxVolume*SFX_BOOST:0,audioCtx.currentTime,.02);updateAudioControls()};$('#volume').onchange=()=>playSfx('select');
document.addEventListener('pointerdown',audioReady,{capture:true});document.addEventListener('keydown',audioReady,{capture:true});updateAudioControls();
const dialogue={1:CHARACTER_LINES.hina,2:CHARACTER_LINES.tsumugi,3:CHARACTER_LINES.mio,4:CHARACTER_LINES.nyx,5:CHARACTER_LINES.felicia};
function say(i,event){if(!i){G.speech='あなた「'+(CHARACTER_LINES.player[event]||CHARACTER_LINES.player.default)+'」';return}let valid=a=>Array.isArray(a)?a.filter(s=>typeof s==='string'&&s.trim()):[],lines=valid(dialogue[castId(i)][event]);if(!lines.length)lines=valid(dialogue[castId(i)].discard);if(!lines.length)lines=['……'];G.dialogueLast??={};let key=i+':'+event,choices=lines.filter(s=>s!==G.dialogueLast[key]),line=choices[Math.floor(Math.random()*choices.length)]||lines[0];G.dialogueLast[key]=line;G.speech=seatPerson(i).name+'「'+line+'」'}
// Persist the pending action so pausing/reloading during the beat cannot skip it.
const immediateCall=applyCall,immediateKan=declareKan,immediateWin=finishWin;
function reactionDelay(){return Math.max(1100,1650/speed)}
function deferReaction(action){clearTimeout(timer);G.reaction={...action,previousPhase:G.phase};G.phase='reaction';selected=-1;save();render();queue(completeReaction,reactionDelay())}
function completeReaction(){if(G.phase!=='reaction'||!G.reaction)return;const r=G.reaction;G.reaction=null;G.phase=r.previousPhase;if(r.kind==='call')immediateCall(r.option);else if(r.kind==='kan')immediateKan(r.option);else immediateWin(r.winner,r.from,r.tile,r.score)}
applyCall=function(o){if(o.i!==0){deferReaction({kind:'call',option:o});return}immediateCall(o)};
declareKan=function(o){if(G.turn!==0){deferReaction({kind:'kan',option:o});return}immediateKan(o)};
finishWin=function(winner,from,t,r){if(winner!==0){deferReaction({kind:'win',winner,from,tile:t,score:r});return}immediateWin(winner,from,t,r)};
const feedbackRenderActions=renderActions;
renderActions=function(){if(G.phase==='reaction'){$('#status').textContent='他家の応答を待っています…';$('#actions').innerHTML='<span class="waiting">少しお待ちください…</span>';return}feedbackRenderActions()};
resumeButton=function(){let d=stored();$('#resume-wrap').innerHTML=d&&!d.finished?'<button id="resume" class="quiet resume">中断した対局を再開 →</button>':'';if($('#resume'))$('#resume').onclick=()=>{G=stored();enterGame();render();if(G.phase==='result')showResult();else if(G.phase==='reaction')queue(completeReaction,reactionDelay());else if(G.phase==='draw')queue(draw);else if(G.phase==='discard')continueTurn()}};
resumeButton();

let cutInTimer=null,cutInDone=null,cutInActive=false;
function endCutIn(){if(!cutInActive)return;clearTimeout(cutInTimer);cutInTimer=null;cutInActive=false;$('#modal').classList.remove('cutin-dialog');$('#modal').close();let done=cutInDone;cutInDone=null;if(done)done()}
function showCutIn(i,event,done=null){if(!i){if(done)done();return}clearTimeout(cutInTimer);cutInActive=true;cutInDone=done;const label={riichi:'リーチ',ron:'ロン',tsumo:'ツモ'}[event],en={riichi:'RIICHI',ron:'RON',tsumo:'TSUMO'}[event];let face={...G.players[i],riichi:true};$('#modal').classList.add('cutin-dialog');openModal(`<div class="cutin-scene cast-${castId(i)}"><div class="cutin-art">${portrait(i,face)}</div><div class="cutin-copy"><span class="cutin-en">${en}</span><h2>${label}<span>！</span></h2><div class="cutin-name">${seatPerson(i).name} <small>${seatPerson(i).roman}</small></div><p>${escapeText(G.speech)}</p></div></div>`);cutInTimer=setTimeout(endCutIn,2200)}
$('#modal').addEventListener('cancel',e=>{if(cutInActive){e.preventDefault();endCutIn()}});

function announceRoundStart(){const worried=[1,2,3].filter(i=>G.players[i].score<10000);if(!worried.length){say(1+G.round%3,'start');return}let lines=[];for(const i of worried){say(i,'lowScore');lines.push(G.speech);log(G.speech)}G.speech=lines.join('\n')}


function nagashiWinners(){return G.players.map((p,i)=>({p,i})).filter(({p})=>p.melds.length===0&&p.river.length>0&&p.river.every(r=>MJ.terminal(r.t)&&!r.taken)).map(({i})=>i)}
function settleNagashi(){const winners=nagashiWinners();if(!winners.length)return false;let delta=[0,0,0,0];for(const winner of winners)for(let i=0;i<4;i++)if(i!==winner){let pay=(winner===G.dealer||i===G.dealer?4000:2000)+G.honba*100;delta[i]-=pay;delta[winner]+=pay}let first=winners.slice().sort((a,b)=>wind(a)-wind(b))[0];delta[first]+=G.pot*1000;G.pot=0;G.players.forEach((p,i)=>p.score+=delta[i]);G.result={type:'nagashi',winners,delta,repeat:winners.includes(G.dealer)};G.phase='result';G.speech=winners.map(i=>seatPerson(i).name+'が流し満貫を達成しました。').join('\n');log(G.speech);playSfx('tsumo');save();render();showResult();return true}
function showNagashiResult(){const r=G.result;openModal(`<span class="badge">NAGASHI MANGAN</span><h2>流し満貫</h2><div class="yaku"><div class="limit-title">満貫</div>${r.winners.map(i=>seatPerson(i).name).join('・')}<br>么九牌だけを捨て、鳴かれずに流局。満貫ツモの点数を精算します。</div>${G.players.map((p,i)=>`<div class="result-row"><span>${p.name}</span><span>${r.delta[i]>0?'+':''}${fmt(r.delta[i])} <b>${fmt(p.score)}</b></span></div>`).join('')}<p>${r.repeat?'親の流し満貫で連荘します。':'次の局へ進みます。'}</p><button id="next" class="primary">${isEndAfterResult()?'対局結果を見る':'次の局へ →'}</button>`);$('#next').onclick=advance}

